// ── STORAGE ──────────────────────────────────────────────────
const sGet = async (k) => {
  try {
    if (!window.storage) return null;
    const r = await window.storage.get(k);
    return r ? JSON.parse(r.value) : null;
  } catch { return null; }
};
const sSet = async (k, v) => {
  try {
    if (!window.storage) return;
    await window.storage.set(k, JSON.stringify(v));
  } catch(e) { console.error(e); }
};

// ── UTILS ────────────────────────────────────────────────────
// Fecha LOCAL de hoy (Hermosillo), NO UTC: new Date().toISOString() daba el día siguiente después de las 5pm
// (17:00 local = 00:00 UTC). Se construye desde los componentes locales, igual que hoyLocal en MiniCalendario.
const hoy = () => { const n = new Date(); return `${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,"0")}-${String(n.getDate()).padStart(2,"0")}`; };
const ahora = () => new Date().toLocaleTimeString("es-MX", { hour:"2-digit", minute:"2-digit" });
const fmtF = (f) => {
  if (!f) return "";
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(f)) return f; // ya está en DD/MM/YYYY
  const parts = f.split("-");
  if (parts.length < 3 || !parts[2]) return f;
  return parts[2]+"/"+parts[1]+"/"+parts[0];
};
// Normaliza fecha a DD/MM/YYYY sea cual sea su formato de entrada
const normDate = (f) => {
  if (!f) return "—";
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(f)) return f;
  if (/^\d{4}-\d{2}-\d{2}$/.test(f)) return f.split("-").reverse().join("/");
  return f;
};
// Convierte DD/MM/YYYY o D/M/YYYY (formato Tanita, día PRIMERO) a ISO YYYY-MM-DD para inputs type=date.
// Si ya viene en ISO la deja igual. Si no puede parsear devuelve "".
const toISODate = (f) => {
  if (!f) return "";
  const s = String(f).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (!m) return "";
  const [, d, mo, y] = m;
  return `${y}-${mo.padStart(2,"0")}-${d.padStart(2,"0")}`;
};
// Convierte una fecha clínica (YYYY-MM-DD o DD/MM/YYYY) a timestamp para ordenar cronológicamente
const parseFechaClinica = (f) => {
  if (!f) return 0;
  if (/^\d{4}-\d{2}-\d{2}/.test(f)) return new Date(f.slice(0,10)+"T00:00:00").getTime();
  const [d,m,y] = f.split("/");
  return new Date(+y,+(m||1)-1,+(d||1)).getTime();
};
// Comparador para .sort() — siempre sobre una copia, nunca mutar el array original
const porFechaClinica = (a,b) => parseFechaClinica(a.fecha) - parseFechaClinica(b.fecha);
// Migración puntual: genera la "Consulta 1" faltante para pacientes creados antes del fix f8c0f70
// (composición inicial en p.composicion sin consulta vinculada en p.consultas).
// Devuelve el paciente actualizado, o null si no hay nada que migrar. Idempotente (seguro de correr varias veces).
const migrarConsultaInicial = (p) => {
  const cons = p.consultas || [];
  // Si ya hay una consulta real (no solo-cita) → nada que reparar.
  if (cons.some(c => !c.esSoloCita)) return null;
  const comps = [...(p.composicion||[])].filter(c=>c.peso||c.grasa).sort(porFechaClinica);
  const primera = comps[0] || null;   // puede no haber báscula: la Consulta 1 se crea igual desde el expediente
  // Ya vinculada por id, o ya existe una consulta en esa misma fecha → no migrar.
  const yaVinculada = primera && primera.id && cons.some(c => c.id === primera.id);
  const mismaFecha  = primera && cons.some(c => !c.esSoloCita && normDate(c.fecha) === normDate(primera.fecha));
  if (yaVinculada || mismaFecha) return null;
  const cid = (primera && primera.id) || crypto.randomUUID();
  const compConId = primera ? (primera.id ? primera : {...primera, id:cid}) : null; // vincula la composición si existe
  const consultaInicial = {
    id: cid,
    fecha: (primera && primera.fecha) || p.fechaInicio || hoy(),
    hora: (primera && primera.hora) || ahora(),
    peso: (primera && primera.peso) || "",
    ca:(p.ef&&p.ef.ca)||"", ta:(p.ci&&p.ci.ta)||"", fc:(p.ci&&p.ci.fc)||"", spo2:(p.ef&&p.ef.spo2)||"",
    glucosaCapilar:(p.ef&&p.ef.glucosaCapilar)||"",
    subjetivo: "(Consulta inicial — migrada automáticamente, datos originales no capturados en el sistema)",
    efectos: "", respuesta: "",
    plan: "", cambioDosis: "", origenMed: "",
    medicamento:(p.ci&&p.ci.glp1)||"", dosis:(p.ci&&p.ci.dosis)||"",
    comp: compConId ? {...compConId} : {},
  };
  const composicion = (compConId && !primera.id)
    ? (p.composicion||[]).map(c => c===primera ? compConId : c)
    : (p.composicion||[]);
  return { ...p, composicion, consultas: [...(p.consultas||[]), consultaInicial] };
};
// Helpers de horario (compartidos por ModalAgenda y ModalConsulta)
const hhmmAMin = (s) => { const [h,m]=(s||"0:0").split(":").map(Number); return (h||0)*60+(m||0); };
const minAHhmm = (n) => `${String(Math.floor(n/60)).padStart(2,"0")}:${String(n%60).padStart(2,"0")}`;
// Horarios de consultorio: L-V 9-13 y 15-18, Sáb 10-13, Dom cerrado (slots cada 30min que quepan según duración)
const generarHorariosClinica = (fechaStr, duracionMin=30) => {
  if (!fechaStr) return [];
  const dow = new Date(fechaStr+"T00:00:00").getDay();
  if (dow === 0) return [];
  const bloques = dow === 6 ? [[10*60,13*60]] : [[9*60,13*60],[15*60,18*60]];
  const horas = [];
  bloques.forEach(([ini,fin]) => { for (let t=ini; t+duracionMin<=fin; t+=30) horas.push(minAHhmm(t)); });
  return horas;
};
// Abreviación de medicamento para el título del evento GCal
const abrevMed = (med) => {
  if (!med) return "";
  const m = med.toLowerCase();
  if (m.includes("mounjaro")) return "MOUN";
  if (m.includes("wegovy"))   return "WEG";
  if (m.includes("ozempic"))  return "OZE";
  if (m.includes("saxenda"))  return "SAX";
  return med.replace(/[^a-zA-Z]/g,"").slice(0,4).toUpperCase();
};

// ── TRATAMIENTO ACTUAL (fuente de verdad p.tratamiento) — Fase 1: solo escritura ──
// Normaliza cualquier formato (cita, consulta full-name, alta) al canónico MOUN/WEG · "5mg" · FARM/CONS.
const _canonMed = (m) => {
  if (!m) return null;
  const u = String(m).toUpperCase();
  if (/MOUN|TIRZ/.test(u)) return "MOUN";
  if (/WEG|SEMA|OZEM/.test(u)) return "WEG";
  return null; // desconocido → no forzamos (no pisamos con basura)
};
const _canonOrigen = (o) => {
  if (!o) return null;
  const u = String(o).toUpperCase();
  if (u.startsWith("FARM")) return "FARM";      // "FARM" o "Farmacia"
  if (u.startsWith("CONS") || u.startsWith("CON")) return "CONS"; // "CONS" o "Consultorio" o "CON"
  return null;
};
const _canonDosis = (d) => {
  if (!d) return null;
  const s = String(d).trim();
  if (/^\d+(\.\d+)?\s*mg$/i.test(s)) return s.replace(/\s+/g,"").toLowerCase(); // "5 mg"→"5mg"
  const num = s.match(/^(\d+(?:\.\d+)?)$/);
  if (num) return num[1] + "mg"; // "5"→"5mg"
  return s; // texto libre → conservar tal cual (no perder el dato)
};
// Fusiona el tratamiento actual con cambios, SOLO pisando campos que traigan valor (nunca borra con null).
const mergeTratamiento = (actual, cambios) => {
  const med = _canonMed(cambios && cambios.medicamento);
  const dos = _canonDosis(cambios && cambios.dosis);
  const ori = _canonOrigen(cambios && cambios.origen);
  const next = { ...(actual || {}) };
  if (med) next.medicamento = med;
  if (dos) next.dosis = dos;
  if (ori) next.origen = ori;
  next.actualizado = new Date().toISOString();
  return next;
};
// Persiste el tratamiento en el paciente (para escritores de CITA). Seguro si no hay paciente. Graceful.
const actualizarTratamientoPaciente = async (paciente, cambios) => {
  try {
    if (!paciente || !paciente.id) return;                 // cita rápida sin expediente → no hace nada
    if (!(cambios && (cambios.medicamento || cambios.dosis || cambios.origen))) return;
    const next = mergeTratamiento(paciente.tratamiento, cambios);
    await savePaciente({ ...paciente, tratamiento: next });
  } catch(e) { console.warn("actualizarTratamientoPaciente (no crítico):", e); }
};

// ── FASE 3 — Lectura: p.tratamiento como fuente de verdad, con fallback legacy p.ci.glp1 ──
const MED_NOMBRE = { MOUN:"Mounjaro", WEG:"Wegovy" };
const ORIGEN_NOMBRE = { FARM:"Farmacia", CONS:"Consultorio" };
// Resuelve el tratamiento efectivo del paciente: p.tratamiento (principal) o fallback legacy p.ci.glp1 (canónico).
const tratamientoEfectivo = (p) => {
  const t = p && p.tratamiento;
  if (t && t.medicamento) return { medicamento: t.medicamento, dosis: t.dosis||null, origen: t.origen||null };
  const glp = (p && p.ci && p.ci.glp1) || "";
  if (!glp) return { medicamento:null, dosis:null, origen:null };
  const dm = glp.match(/([\d.]+\s*mg)/i);
  return { medicamento: _canonMed(glp), dosis: _canonDosis(dm ? dm[1] : ((p.ci && p.ci.dosis) || null)), origen: null };
};
// Solo el nombre del medicamento ("Mounjaro"/"Wegovy"/"") — para pills/chips.
const medLegibleCorto = (trat) => (trat && trat.medicamento) ? (MED_NOMBRE[trat.medicamento] || trat.medicamento) : "";
// Texto legible completo: "Mounjaro 5mg" (y "· Farmacia" si conOrigen). "" si no hay medicamento.
const formatearTratamiento = (trat, { conOrigen=false } = {}) => {
  if (!trat || !trat.medicamento) return "";
  let s = MED_NOMBRE[trat.medicamento] || trat.medicamento;
  if (trat.dosis) s += " " + trat.dosis;
  if (conOrigen && trat.origen) s += " · " + (ORIGEN_NOMBRE[trat.origen] || trat.origen);
  return s;
};

// FASE 2 — Migración: puebla p.tratamiento de todos los pacientes desde su CITA MÁS RECIENTE con medicamento
// (fallback: última consulta con medicamento). Idempotente y conservador: no pisa un tratamiento ajustado a
// mano más reciente que la fuente. Reusa mergeTratamiento/actualizarTratamientoPaciente (Fase 1). Lee datos FRESCOS.
const migrarTratamientos = async () => {
  let pacientes = [], citas = [];
  try { pacientes = await getPacientes(); } catch(e){ console.error("migrarTratamientos/pacientes:", e); return { error:true }; }
  try { citas = await listarCitas({}); } catch(e){ console.error("migrarTratamientos/citas:", e); }
  const porPac = {};
  citas.forEach(c => { if (c.pacienteId) (porPac[c.pacienteId]=porPac[c.pacienteId]||[]).push(c); });

  let migrados=0, saltados=0, respetados=0;
  for (const p of pacientes) {
    // 1) Cita más reciente (mayor inicio) con medicamento → formato ya canónico.
    const citaSrc = (porPac[p.id]||[]).filter(c=>c.medicamento).sort((a,b)=>new Date(b.inicio)-new Date(a.inicio))[0] || null;
    let cambios = null, srcTs = 0;
    if (citaSrc) {
      cambios = { medicamento: citaSrc.medicamento, dosis: citaSrc.dosis, origen: citaSrc.origen };
      srcTs = new Date(citaSrc.ultimaModificacion || citaSrc.inicio || 0).getTime();
    } else {
      // 2) Fallback: última consulta con medicamento (full→abrev / Farmacia→FARM lo hace mergeTratamiento).
      const cons = [...(p.consultas||[])].filter(c=>!c.esSoloCita && c.medicamento).sort(porFechaClinica).slice(-1)[0];
      if (cons) {
        cambios = { medicamento: cons.medicamento, dosis: cons.dosis, origen: cons.origenMed };
        srcTs = parseFechaClinica(cons.fecha) || 0;
      }
    }
    if (!cambios) { saltados++; continue; }               // sin datos → no inventa
    // 3) Conservador/idempotente: si el tratamiento ya guardado es MÁS RECIENTE que la fuente, respetarlo.
    const actualTs = (p.tratamiento && p.tratamiento.actualizado) ? new Date(p.tratamiento.actualizado).getTime() : 0;
    if (actualTs && actualTs > srcTs) { respetados++; continue; }
    try { await actualizarTratamientoPaciente(p, cambios); migrados++; }
    catch(e){ console.warn("migrarTratamientos/cita:", e); saltados++; }
  }
  return { migrados, saltados, respetados };
};

// Slots de GCal ocupados en una fecha dada (reusa el array gcalEventos ya cargado a nivel App)
const gcalOcupadasEnFecha = (gcalEventos, fechaSel) => (gcalEventos||[]).flatMap(ev => {
  const f = (ev.start?.dateTime||ev.start?.date||"").split("T")[0];
  if (f !== fechaSel || !ev.start?.dateTime) return [];
  const h = ev.start.dateTime.split("T")[1]?.slice(0,5)||"";
  if (!h) return [];
  const durMs = ev.end?.dateTime ? new Date(ev.end.dateTime)-new Date(ev.start.dateTime) : 30*60000;
  return [{ ini: hhmmAMin(h), fin: hhmmAMin(h)+Math.max(15,Math.round(durMs/60000)), pac: ev.summary||"GCal", hora: h }];
});
const fmtFLargo = (f) => {
  if (!f) return "";
  const iso = toISODate(f) || f; // acepta DD/MM/YYYY (formato Tanita) además de ISO
  const d = new Date(iso+"T12:00:00");
  if (isNaN(d.getTime())) return normDate(f); // fallback legible si no se puede parsear
  return d.toLocaleDateString("es-MX",{weekday:"long",day:"numeric",month:"long"});
};
const calcIMC = (p,t) => {
  if (!p||!t) return "";
  const tm = parseFloat(t)/100;
  return (parseFloat(p)/(tm*tm)).toFixed(1);
};
// Calcula la edad a partir de fecha YYYY-MM-DD
const calcEdad = (fechaNac) => {
  if (!fechaNac) return "";
  try {
    const hoy = new Date();
    const nac = new Date(fechaNac);
    if (isNaN(nac.getTime())) return "";
    let edad = hoy.getFullYear() - nac.getFullYear();
    const m = hoy.getMonth() - nac.getMonth();
    if (m < 0 || (m === 0 && hoy.getDate() < nac.getDate())) edad--;
    return edad >= 0 && edad <= 130 ? String(edad) : "";
  } catch(e) { return ""; }
};

// HOMA-IR = (Glucosa mg/dL × Insulina μU/mL) / 405
// <2.5 normal · 2.5-3.8 resistencia leve · >3.8 resistencia insulínica
const calcHOMA = (glucosa, insulina) => {
  const g = parseFloat(glucosa);
  const i = parseFloat(insulina);
  if (isNaN(g) || isNaN(i) || g <= 0 || i <= 0) return "";
  const homa = (g * i) / 405;
  return homa.toFixed(2);
};

// Enviar mensaje WhatsApp con manejo robusto de teléfono faltante o malformado
const enviarWA = (telefono, mensaje) => {
  const tel = String(telefono||"").replace(/\D/g,"");
  if (!tel || tel.length < 10) {
    try {
      navigator.clipboard.writeText(mensaje);
      alert("⚠️ Este paciente no tiene teléfono registrado.\n\nEl mensaje se copió al portapapeles. Pégalo manualmente en WhatsApp.");
    } catch(e) {
      alert("⚠️ Este paciente no tiene teléfono registrado.");
    }
    return false;
  }
  const num = tel.startsWith("52") ? tel : (tel.length===10 ? "52"+tel : tel);
  const url = "https://wa.me/"+num+"?text="+encodeURIComponent(mensaje);
  window.open(url, "_blank");
  return true;
};

// Abre Google Calendar con los datos de la cita prellenados
const agregarAGoogleCalendar = async (nombre, telefono, fecha, hora, tipoCita, duracionMin) => {
  if (isGoogleAuthorized()) {
    const resultado = await crearEventoGCal(nombre, telefono, fecha, hora, tipoCita, duracionMin);
    if (resultado) {
      alert("✅ Cita agregada a Google Calendar");
    } else {
      // Fallback: abrir URL manual
      const [year, month, day] = fecha.split("-");
      const [hr, mn] = hora.split(":");
      const ini = `${year}${month}${day}T${hr}${mn}00`;
      const iniDate = new Date(parseInt(year), parseInt(month)-1, parseInt(day), parseInt(hr), parseInt(mn));
      const finDate = new Date(iniDate.getTime() + (duracionMin||30)*60000);
      const fin = `${finDate.getFullYear()}${String(finDate.getMonth()+1).padStart(2,"0")}${String(finDate.getDate()).padStart(2,"0")}T${String(finDate.getHours()).padStart(2,"0")}${String(finDate.getMinutes()).padStart(2,"0")}00`;
      const tipo = tipoCita === "primera" ? "Primera vez" : "Seguimiento";
      const url = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(nombre+" — "+tipo)}&dates=${ini}/${fin}&location=${encodeURIComponent("Av. Adolfo de la Huerta 200A 2do piso, Hermosillo")}`;
      window.open(url, "_blank");
    }
  } else {
    authorizeGoogleCalendar();
  }
};

const gradoIMC = (v) => {
  const n = parseFloat(v);
  if (!n) return "";
  if (n<18.5) return "Bajo peso";
  if (n<25)   return "Normal";
  if (n<30)   return "Sobrepeso";
  if (n<35)   return "Obesidad I";
  if (n<40)   return "Obesidad II";
  return "Obesidad III";
};
const diasDesde = (f) => {
  if (!f) return null;
  return Math.floor((Date.now()-new Date(f+"T00:00:00").getTime())/86400000);
};
const diasHasta = (f) => {
  if (!f) return null;
  return Math.ceil((new Date(f+"T00:00:00").getTime()-Date.now())/86400000);
};
// Estado de labs a partir de UNA fecha y un plazo de vencimiento (días).
// limiteDias por defecto 90 (≈3 meses); el umbral ámbar "por vencer" es limiteDias-10.
const estadoLabs = (fecha, limiteDias=90) => {
  const d = diasDesde(fecha);
  const ambar = limiteDias-10;
  if (d===null) return {nivel:"amarillo",dias:null,restan:null,msg:"Sin laboratorios registrados — solicitar"};
  if (d>=limiteDias) return {nivel:"rojo",dias:d,restan:0,msg:"Labs vencidos hace "+(d-limiteDias)+" días"};
  if (d>=ambar) return {nivel:"amarillo",dias:d,restan:limiteDias-d,msg:"Labs vencen en "+(limiteDias-d)+" días"};
  return {nivel:"verde",dias:d,restan:limiteDias-d,msg:"Labs al día"};
};

// Estado de labs de un PACIENTE, aplicando el override manual por precedencia:
// si p.labsOverride existe y su fecha es más reciente que el último lab real (o no hay lab real),
// se cuenta desde el override con plazo meses*30. Un lab real posterior lo domina automáticamente.
const estadoLabsPaciente = (p) => {
  const realLast = [
    ...((p.resultadosLabs||[]).map(r=>r.fecha)),
    ...((p.laboratorios||[]).map(l=>l.fecha)),
    p.labsI?.fecha,
  ].filter(Boolean).sort().slice(-1)[0] || null;
  const ov = p.labsOverride;
  if (ov?.fecha && (!realLast || ov.fecha > realLast))
    return estadoLabs(ov.fecha, (ov.meses||3)*30);
  return estadoLabs(realLast, 90);
};

// ── Composición corporal: helpers puros compartidos (expediente + DocProgreso) ──
// Grasa en kg de una medición: campo directo masaGrasa (Tanita); si falta, peso×grasa/100.
const grasaKgDe = (c) => {
  if(!c) return null;
  const dir=parseFloat(c.masaGrasa);
  if(!isNaN(dir)&&dir>0) return parseFloat(dir.toFixed(1));
  const g=parseFloat(c.grasa), pe=parseFloat(c.peso);
  return (!isNaN(g)&&!isNaN(pe)) ? parseFloat((g/100*pe).toFixed(1)) : null;
};
// Masa libre de grasa (kg): campo masaLibreGrasa (Tanita); si falta, peso×(1-grasa/100).
const ffmDe = (c) => {
  if(!c) return null;
  const real=parseFloat(c.masaLibreGrasa);
  if(!isNaN(real)) return real;
  const pe=parseFloat(c.peso), g=parseFloat(c.grasa);
  return (!isNaN(pe)&&!isNaN(g)) ? pe*(1-g/100) : null;
};
// FFMI = FFM / talla(m)². tallaCm en cm.
const ffmiDe = (c, tallaCm) => {
  const ffm=ffmDe(c);
  const tM=(Number(tallaCm)||0)/100;
  return (tM>0 && ffm!=null) ? parseFloat((ffm/(tM*tM)).toFixed(1)) : null;
};

// ── CATÁLOGOS ────────────────────────────────────────────────
const GLPS = [
  "Wegovy (Semaglutida) 0.25mg","Wegovy (Semaglutida) 0.5mg",
  "Wegovy (Semaglutida) 1.0mg","Wegovy (Semaglutida) 1.7mg","Wegovy (Semaglutida) 2.4mg",
  "Mounjaro (Tirzepatida) 2.5mg","Mounjaro (Tirzepatida) 5mg","Mounjaro (Tirzepatida) 7.5mg",
  "Mounjaro (Tirzepatida) 10mg","Mounjaro (Tirzepatida) 12.5mg","Mounjaro (Tirzepatida) 15mg",
];

const extraerNombreGCal = (titulo) => {
  if (!titulo?.trim()) return null;
  // Tomar solo la parte antes del separador (-, —, –)
  let s = titulo.split(/\s*[-—–]\s*/)[0].trim();
  // Quitar palabras clave de estado/tipo
  s = s.replace(/\b(probable|domicilio|cita|seguimiento|primera\s+vez?|primera|vez|farm|glp-?1?)\b/gi, "");
  // Quitar abreviaciones de medicamentos
  s = s.replace(/\b(moun|weg|lira|ozem|sema|tirz)\b/gi, "");
  // Quitar patrones de dosis: "2.5mg", "0.5 mg", "10mg"
  s = s.replace(/\b\d+[\d.]*\s*m[gl]\b/gi, "");
  // Quitar ordinales: "1ra", "2da", "3ra", "4ta"
  s = s.replace(/\b\d+[a-záéíóú]+\b/gi, "");
  // Colapsar espacios y limpiar puntuación sobrante
  s = s.replace(/[^a-záéíóúüñA-ZÁÉÍÓÚÜÑ\s.]/g, " ").replace(/\s{2,}/g, " ").trim();
  // Requiere mínimo 2 palabras de 2+ caracteres para ser nombre válido
  const palabras = s.split(/\s+/).filter(w => w.length >= 2);
  return palabras.length >= 2 ? s : null;
};

const buildGCalTitulo = (pac, tipoCita) => {
  const num = (pac.consultas||[]).length;
  const ordinal = n => n===1?"1ra":n===2?"2da":n===3?"3ra":n===4?"4ta":n===5?"5ta":n+"a";
  if (tipoCita === "primera") return `${pac.nombre} - ${ordinal(num)} consulta`;
  const recetasGlp1 = (pac.recetas||[]).filter(r=>r.tipo==="glp1");
  const ultima = recetasGlp1[recetasGlp1.length-1];
  if (!ultima?.med) return `${pac.nombre} - ${ordinal(num)} consulta`;
  const medL = ultima.med.toLowerCase();
  const abrev = (medL.includes("tirzepatida")||medL.includes("mounjaro")) ? "MOUN"
    : (medL.includes("semaglutida")||medL.includes("wegovy")||medL.includes("ozempic")) ? "WEG"
    : medL.includes("liraglutida") ? "LIRA" : "";
  const dosis = ultima.med.split(" ").at(-1)||"";
  return `${pac.nombre} - ${ordinal(num)} ${abrev ? abrev+" "+dosis : ultima.med}`.trim();
};

// ── AGENDA v2 — Modelo de cita + identidad única ─────────────────────────────
// FASE A: solo define el modelo y los helpers. La UI (ModalAgenda/Calendario) se migra en Fase D.
const TIPOS_CITA_V2 = ["primera_vez","seguimiento"];
const ESTADOS_CITA_V2 = ["agendada","confirmada","cancelada","completada"];

// Calcula el fin (ISO local naive YYYY-MM-DDTHH:MM:00) sumando la duración al inicio.
const calcFinCitaISO = (fecha, hora, durMin) => {
  const [y,m,d] = (fecha||"").split("-").map(Number);
  const [hh,mm] = (hora||"0:0").split(":").map(Number);
  const ini = new Date(y, (m||1)-1, d||1, hh||0, mm||0);
  const fin = new Date(ini.getTime() + (durMin||30)*60000);
  const z = n => String(n).padStart(2,"0");
  return `${fin.getFullYear()}-${z(fin.getMonth()+1)}-${z(fin.getDate())}T${z(fin.getHours())}:${z(fin.getMinutes())}:00`;
};

// Título consistente para Google Calendar a partir de los campos estructurados de la cita.
// Omite las partes nulas. Ej: "Cony Chávez · SEG · MOUN 5mg · 3ra" | "Claudia Valle · PRIM".
const generarTituloCita = (cita) => {
  if (!cita) return "";
  const ordinal = (n) => { const x=parseInt(n); if(!x) return null;
    return x===1?"1ra":x===2?"2da":x===3?"3ra":x===4?"4ta":x===5?"5ta":x+"a"; };
  const tipoAbrev = { primera_vez:"PRIM", seguimiento:"SEG" };
  const med = cita.medicamento ? [cita.medicamento, cita.dosis].filter(Boolean).join(" ") : null;
  return [
    cita.pacienteNombre || null,
    tipoAbrev[cita.tipo] || null,
    med,
    cita.origen || null,        // 'FARM' | 'CONS' — después de med+dosis, antes del nº de visita
    ordinal(cita.numeroVisita),
  ].filter(Boolean).join(" · ");
};

// Construye una cita v2 con la forma objetivo (sin googleEventId aún).
const construirCitaV2 = ({ id, googleEventId=null, calendarId=null, pacienteId=null,
  pacienteNombre="", tipo="seguimiento", medicamento=null, dosis=null, origen=null, numeroVisita=null,
  fecha, hora, estado="agendada", origenUltimoCambio="app" } = {}) => {
  const dur = tipo === "primera_vez" ? 60 : 30;
  const cita = {
    id: id || crypto.randomUUID(),
    googleEventId: googleEventId,
    calendarId: calendarId,
    pacienteId: pacienteId,
    pacienteNombre: pacienteNombre,
    tipo: tipo,
    medicamento: medicamento || null,
    dosis: dosis || null,
    origen: origen || null,
    numeroVisita: (numeroVisita!=null && numeroVisita!=="") ? parseInt(numeroVisita) : null,
    inicio: `${fecha}T${(hora||"00:00")}:00`,
    fin: calcFinCitaISO(fecha, hora, dur),
    estado: estado,
    version: 1,
    ultimaModificacion: new Date().toISOString(),
    origenUltimoCambio: origenUltimoCambio,
    pendienteSincronizar: false,
    tituloGenerado: "",
  };
  cita.tituloGenerado = generarTituloCita(cita);
  return cita;
};

// Valida una cita v2. Devuelve array de errores ([] = válida).
const validarCitaV2 = (cita) => {
  const e = [];
  if (!cita) return ["cita vacía"];
  if (!cita.pacienteNombre) e.push("falta pacienteNombre");
  if (!TIPOS_CITA_V2.includes(cita.tipo)) e.push("tipo inválido");
  if (!ESTADOS_CITA_V2.includes(cita.estado)) e.push("estado inválido");
  if (!cita.inicio || isNaN(new Date(cita.inicio).getTime())) e.push("inicio inválido");
  if (!cita.fin || isNaN(new Date(cita.fin).getTime())) e.push("fin inválido");
  return e;
};

// Agenda ATÓMICA con identidad única: una cita = un registro = un evento, enlazados por googleEventId
// desde el nacimiento. Crea el evento en GCal UNA sola vez ANTES de persistir; nunca dos veces.
// `persistirCita(citaCompleta)` es el callback que escribe en Supabase (lo inyecta la UI en Fase D).
const agendarCitaV2 = async (datosCita, persistirCita) => {
  const cita = construirCitaV2(datosCita);
  const errs = validarCitaV2(cita);
  if (errs.length) { console.error("Cita v2 inválida:", errs); return { ok:false, errores:errs, cita:null }; }

  // Resolver calendario dedicado (lo crea si no existe).
  const calendarId = await obtenerOCrearCalendarioConsultorio();
  cita.calendarId = calendarId;
  cita.tituloGenerado = generarTituloCita(cita);

  // Crear el evento en GCal (un único insert) y capturar su id.
  let evento = null;
  if (calendarId) {
    evento = await crearEventoEnCalendario(calendarId, {
      summary: cita.tituloGenerado,
      descripcion: `Tipo: ${cita.tipo}${cita.medicamento?` · ${cita.medicamento} ${cita.dosis||""}`.trim():""}`,
      inicioISO: cita.inicio,
      finISO: cita.fin,
      colorId: cita.tipo==="primera_vez" ? "9" : "2",
      location: "Av. Adolfo de la Huerta 200A 2do piso, Col. Pitic, Hermosillo, Sonora",
    });
  }

  if (evento && evento.id) {
    cita.googleEventId = evento.id;     // enlace establecido desde el nacimiento
    cita.pendienteSincronizar = false;
  } else {
    // GCal falló (o sin conexión): persistir igual, marcada para reintento. NUNCA se crea el evento dos veces.
    cita.googleEventId = null;
    cita.pendienteSincronizar = true;
  }

  // Persistir UNA sola vez, con el googleEventId ya enlazado.
  if (typeof persistirCita === "function") {
    try { await persistirCita(cita); }
    catch(e) { console.error("Error persistiendo cita v2:", e); return { ok:false, errores:["persist falló"], cita }; }
  }
  return { ok:true, cita };
};

// ── FASE D2-A — Escritura app → Google Calendar (calendario dedicado) ────────
// Mapea una cita v2 → opciones de evento para el calendario dedicado.
const citaAEvento = (cita) => ({
  summary: cita.tituloGenerado || generarTituloCita(cita),
  descripcion: `Tipo: ${cita.tipo}`
    + (cita.medicamento ? ` · ${[cita.medicamento, cita.dosis].filter(Boolean).join(" ")}` : "")
    + (cita.origen ? ` · ${cita.origen}` : ""),
  inicioISO: cita.inicio,
  finISO: cita.fin,
  colorId: cita.tipo==="primera_vez" ? "9" : "2",
  location: "Av. Adolfo de la Huerta 200A 2do piso, Col. Pitic, Hermosillo, Sonora",
});

// Crea el evento en GCal para una cita ya persistida. Devuelve {googleEventId, calendarId} o null. NUNCA lanza.
const pushCrearEventoGCal = async (cita) => {
  try {
    if (!isGoogleAuthorized()) return null;
    const calendarId = await obtenerOCrearCalendarioConsultorio();
    if (!calendarId) return null;
    const ev = await crearEventoEnCalendario(calendarId, citaAEvento(cita));
    return (ev && ev.id) ? { googleEventId: ev.id, calendarId } : null;
  } catch(e) { console.warn("GCal crear evento (no crítico):", e); return null; }
};

// Actualiza el evento en GCal de una cita enlazada. Devuelve true si se reflejó. NUNCA lanza.
const pushActualizarEventoGCal = async (cita) => {
  try {
    if (!cita.googleEventId || !isGoogleAuthorized()) return false;
    const calendarId = cita.calendarId || getCalendarioConsultorioId() || await obtenerOCrearCalendarioConsultorio();
    if (!calendarId) return false;
    const ev = await actualizarEventoEnCalendario(calendarId, cita.googleEventId, citaAEvento(cita));
    return !!ev;
  } catch(e) { console.warn("GCal actualizar evento (no crítico):", e); return false; }
};

// Borra el evento en GCal de una cita enlazada. Devuelve true si se borró (o no aplicaba). NUNCA lanza.
const pushBorrarEventoGCal = async (cita) => {
  try {
    if (!cita || !cita.googleEventId || !isGoogleAuthorized()) return false;
    const calendarId = cita.calendarId || getCalendarioConsultorioId() || await obtenerOCrearCalendarioConsultorio();
    if (!calendarId) return false;
    return await borrarEventoEnCalendario(calendarId, cita.googleEventId);
  } catch(e) { console.warn("GCal borrar evento (no crítico):", e); return false; }
};

// A4 — Sincroniza las citas con pendienteSincronizar=true que aún no tienen googleEventId.
// Idempotente: salta las ya enlazadas. NUNCA rompe la app.
const sincronizarPendientes = async () => {
  if (!isGoogleAuthorized()) return { ok:false, motivo:"google_desconectado", sincronizadas:0, total:0 };
  let pendientes = [];
  try { pendientes = (await listarCitas({})).filter(c => c.pendienteSincronizar && !c.googleEventId); }
  catch(e) { console.error("sincronizarPendientes/listar:", e); return { ok:false, motivo:"listar_fallo", sincronizadas:0, total:0 }; }
  if (pendientes.length === 0) return { ok:true, sincronizadas:0, total:0 }; // nada pendiente → no tocar Google (chequeo barato)
  const calendarId = await obtenerOCrearCalendarioConsultorio();
  if (!calendarId) return { ok:false, motivo:"sin_calendario", sincronizadas:0, total:pendientes.length };
  let n = 0;
  for (const c of pendientes) {
    if (c.googleEventId) continue; // idempotente
    try {
      const ev = await crearEventoEnCalendario(calendarId, citaAEvento(c));
      if (ev && ev.id) { await actualizarCita(c.id, { googleEventId: ev.id, calendarId, pendienteSincronizar:false }); n++; }
    } catch(e) { console.warn("sincronizarPendientes/cita:", e); }
  }
  return { ok:true, sincronizadas:n, total:pendientes.length };
};

// ── FASE D2-B — Lectura Google → app ─────────────────────────────────────────
// Config: calendarios personales que cuentan como "ocupado" (array de calendarIds en configuracion).
const getCalendariosOcupado = async () => {
  try { const v = await getConfig("calendarios_ocupado"); return v ? JSON.parse(v) : []; }
  catch(e){ console.warn("getCalendariosOcupado:", e); return []; }
};
const setCalendariosOcupado = async (ids) => {
  try { await setConfig("calendarios_ocupado", JSON.stringify(ids||[])); }
  catch(e){ console.warn("setCalendariosOcupado:", e); }
};

// B1+B2 — Importa cambios del calendario del consultorio a la tabla `citas` (Google → app).
// Resolución de conflictos: gana el timestamp más reciente (ev.updated vs cita.ultimaModificacion).
// Detecta borrados (evento ya no está en Google) → marca la cita como 'cancelada' (conserva el registro).
// NUNCA rompe la app: si Google falla o está desconectado, devuelve {ok:false} y no toca nada.
const importarCambiosConsultorio = async () => {
  if (!isGoogleAuthorized()) return { ok:false, motivo:"desconectado" };
  const calendarId = getCalendarioConsultorioId() || await obtenerOCrearCalendarioConsultorio();
  if (!calendarId) return { ok:false, motivo:"sin_calendario" };
  const desde = new Date(); desde.setHours(0,0,0,0);
  const hasta = new Date(Date.now() + 90*24*60*60*1000);
  let eventos = [];
  try { eventos = await leerEventosDeCalendario(calendarId, { timeMin:desde.toISOString(), timeMax:hasta.toISOString() }); }
  catch(e){ console.warn("importar/leer:", e); return { ok:false, motivo:"lectura_fallo" }; }

  const avisos = []; let nuevas=0, actualizadas=0, canceladas=0;
  const seen = new Set();
  for (const ev of eventos) {
    if (!ev.id || !ev.start?.dateTime) continue;  // ignora eventos de día completo / inválidos
    seen.add(ev.id);
    const inicioISO = ev.start.dateTime;
    const finISO = ev.end?.dateTime || ev.start.dateTime;
    const nombre = (ev.summary||"").split(" · ")[0].trim() || "Cita";
    let cita = null;
    try { cita = await obtenerCitaPorGoogleEventId(ev.id); } catch(e){ continue; }
    if (cita) {
      const gUpd = new Date(ev.updated||0).getTime();
      const lUpd = new Date(cita.ultimaModificacion||0).getTime();
      if (gUpd > lUpd) {   // Google es más reciente → gana Google
        try {
          await actualizarCita(cita.id, { inicio:inicioISO, fin:finISO,
            tituloGenerado: ev.summary||cita.tituloGenerado, pacienteNombre:nombre,
            origenUltimoCambio:"gcal", pendienteSincronizar:false });
          actualizadas++;
          avisos.push(`La cita de ${cita.pacienteNombre} se actualizó desde Google Calendar`);
        } catch(e){ console.warn("importar/actualizar:", e); }
      }
      // Si lo local es más reciente, gana local: no se toca (lo subirá D2-A / sincronizarPendientes).
    } else {
      // Evento creado directamente en Google (ej. desde el teléfono) → alta en la tabla.
      try {
        const nueva = construirCitaV2({ pacienteNombre:nombre, tipo:"seguimiento", fecha:"2000-01-01", hora:"00:00" });
        nueva.inicio = inicioISO; nueva.fin = finISO;
        nueva.googleEventId = ev.id; nueva.calendarId = calendarId;
        nueva.tituloGenerado = ev.summary || nueva.tituloGenerado;
        nueva.origenUltimoCambio = "gcal"; nueva.pendienteSincronizar = false;
        await crearCita(nueva); nuevas++;
      } catch(e){ console.warn("importar/crear:", e); }
    }
  }
  // Detección de borrados: cita con googleEventId que ya no existe en Google → cancelar.
  try {
    const enTabla = await listarCitas({ desde:desde.toISOString(), hasta:hasta.toISOString() });
    for (const c of enTabla) {
      if (c.googleEventId && !seen.has(c.googleEventId) && c.estado!=="cancelada") {
        try {
          await actualizarCita(c.id, { estado:"cancelada", origenUltimoCambio:"gcal" });
          canceladas++;
          avisos.push(`La cita de ${c.pacienteNombre} fue cancelada desde Google Calendar`);
        } catch(e){ console.warn("importar/cancelar:", e); }
      }
    }
  } catch(e){ console.warn("importar/borrados:", e); }
  return { ok:true, nuevas, actualizadas, canceladas, avisos };
};

// B4 — Lee los eventos de los calendarios PERSONALES seleccionados (solo lectura) como bloques "ocupado".
const leerEventosOcupado = async ({ desde, hasta } = {}) => {
  try {
    if (!isGoogleAuthorized()) return [];
    const ids = await getCalendariosOcupado();
    if (!ids.length) return [];
    let cals = [];
    try { cals = await listarCalendariosDisponibles(); } catch(e){ cals = []; }
    const nombreDe = (id) => (cals.find(c=>c.id===id)?.summary) || "Calendario";
    const out = [];
    for (const id of ids) {
      let evs = [];
      try { evs = await leerEventosDeCalendario(id, { timeMin:desde, timeMax:hasta }); } catch(e){ evs = []; }
      for (const ev of evs) {
        const timed = !!ev.start?.dateTime;   // con hora → cuadrícula; sin hora (start.date) → evento de todo el día
        out.push({
          allDay: !timed,
          inicio: timed ? ev.start.dateTime : (ev.start?.date || null),
          fin:    timed ? (ev.end?.dateTime || ev.start.dateTime) : (ev.end?.date || ev.start?.date || null),
          summary: ev.summary||"Ocupado", calendario:nombreDe(id), calendarId:id });
      }
    }
    return out;
  } catch(e){ console.warn("leerEventosOcupado:", e); return []; }
};

// ── DIAGNÓSTICO — Comparar calendario principal de Google vs tabla `citas` (SOLO LECTURA) ─────
// Paleta de colorId de eventos de Google (para que el doctor distinga verde=paciente de otros).
const COLOR_GCAL = { "1":"Lavanda","2":"Verde (Sage)","3":"Morado (Grape)","4":"Rosa (Flamingo)",
  "5":"Amarillo (Banana)","6":"Naranja (Tangerine)","7":"Azul (Peacock)","8":"Gris (Graphite)",
  "9":"Azul (Blueberry)","10":"Verde (Basil)","11":"Rojo (Tomato)" };
const _normNombre = (s) => (s||"").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"")
  .replace(/[^a-z\s]/g," ").replace(/\s+/g," ").trim();
const _palabrasNombre = (s) => _normNombre(s).split(" ").filter(w=>w.length>=3);
const _nombresCompatibles = (a,b) => {
  const pa=_palabrasNombre(a), pb=_palabrasNombre(b);
  if(!pa.length||!pb.length) return false;
  const setB=new Set(pb);
  const comunes=pa.filter(w=>setB.has(w)).length;
  return comunes>=2 || (comunes>=1 && (pa.length===1||pb.length===1));
};

// Parsea el título de un evento de Google → campos estructurados de cita (ayuda, no perfecto).
// Ej: "Martha ... Dancil - 2da MOUN FARM" → {nombre, tipo:seguimiento, numeroVisita:2, medicamento:MOUN, origen:FARM}
const parseTituloCita = (titulo) => {
  const t = (titulo||"").trim();
  // Nombre = primer segmento antes de un separador ( - — – · . ); el resto son datos.
  const partes = t.split(/\s*[-—–·]\s*|\s+\.\s+/).map(s=>s.trim()).filter(Boolean);
  const nombre = (partes[0] || t).trim();
  const restoU = partes.slice(1).join(" ").toUpperCase();

  // Número de visita: ordinal (2da, 3ra, 4ta, 1era…). Un número suelto NO es visita (es dosis).
  let numeroVisita = null;
  const mv = restoU.match(/\b(\d+)\s*(?:DA|RA|ERA|TA|TO|VA|º|°)\b/);
  if (mv) numeroVisita = parseInt(mv[1]);

  // Medicamento
  let medicamento = null;
  if (/MOUN|TIRZ/.test(restoU)) medicamento = "MOUN";
  else if (/WEG|SEMA|OZEM/.test(restoU)) medicamento = "WEG";

  // Dosis: quitar primero el ordinal para no confundirlo; luego buscar número (con o sin MG).
  let restoDosis = restoU;
  if (mv) restoDosis = restoDosis.replace(mv[0], " ");
  let dosis = null;
  const md = restoDosis.match(/(\d+(?:\.\d+)?)\s*MG/) || restoDosis.match(/\b(\d+(?:\.\d+)?)\b/);
  if (md) {
    const val = md[1] + "mg"; // normaliza al formato del selector (5mg, 1.7mg, 2.5mg)
    dosis = (medicamento && DOSIS_POR_MED[medicamento] && !DOSIS_POR_MED[medicamento].includes(val)) ? val : val;
  }

  // Origen
  let origen = null;
  if (/FARM/.test(restoU)) origen = "FARM";
  else if (/CONS/.test(restoU)) origen = "CONS";

  // Tipo: PRIMERA → primera_vez; en cualquier otro caso seguimiento (default).
  const tipo = /PRIMERA/.test(restoU) ? "primera_vez" : "seguimiento";

  return { nombre, tipo, medicamento, dosis: medicamento ? dosis : null, origen, numeroVisita };
};

// Compara el calendario "primary" (My calendar) contra la tabla `citas` desde el 1-jul-2026.
// NO crea/edita/borra nada: solo lee ambas fuentes y devuelve el diagnóstico. Defensivo.
const compararConGoogle = async () => {
  if (!isGoogleAuthorized()) return { conectado:false };
  const desde = "2026-07-01T00:00:00-07:00";
  const hasta = new Date(Date.now() + 90*24*60*60*1000).toISOString();
  let eventos = [], citas = [];
  try { eventos = await leerEventosDeCalendario("primary", { timeMin:desde, timeMax:hasta }); }
  catch(e){ console.warn("comparar/eventos:", e); return { conectado:true, error:"No se pudieron leer los eventos de Google." }; }
  try { citas = await listarCitas({ desde, hasta }); }
  catch(e){ console.warn("comparar/citas:", e); return { conectado:true, error:"No se pudieron leer las citas de la tabla." }; }

  const citasIdx = citas.map(c=>({ nombre:c.pacienteNombre, t:new Date(c.inicio).getTime(), inicio:c.inicio }));
  const evsIdx = eventos.filter(e=>e.start?.dateTime).map(e=>({ e, t:new Date(e.start.dateTime).getTime(), nombre:e.summary||"" }));

  const usados = new Set();
  const faltantes = [];
  let coincidencias = 0;
  for (const ev of evsIdx) {
    const mi = citasIdx.findIndex((ci,idx)=> !usados.has(idx)
      && Math.abs(ci.t-ev.t) <= 5*60000 && _nombresCompatibles(ci.nombre, ev.nombre));
    if (mi >= 0) { coincidencias++; usados.add(mi); }
    else {
      const {fecha,hora} = isoAInputsHmo(ev.e.start.dateTime);
      faltantes.push({ summary: ev.e.summary || "(sin título)", fecha, hora,
        colorId: ev.e.colorId || null,
        color: ev.e.colorId ? (COLOR_GCAL[ev.e.colorId] || ("color "+ev.e.colorId)) : "color del calendario" });
    }
  }
  const soloApp = citasIdx.filter((_,idx)=>!usados.has(idx)).map(ci=>{
    const {fecha,hora} = isoAInputsHmo(ci.inicio);
    return { nombre:ci.nombre, fecha, hora };
  });
  faltantes.sort((a,b)=>(a.fecha+a.hora).localeCompare(b.fecha+b.hora));
  soloApp.sort((a,b)=>(a.fecha+a.hora).localeCompare(b.fecha+b.hora));
  return { conectado:true, coincidencias, faltantes, soloApp, totalGoogle:evsIdx.length, totalTabla:citas.length };
};

// Instante exacto (ms) de una fecha+hora local de Hermosillo (UTC-7 fijo). Para comparación idempotente.
const _instanteHermosillo = (fecha, hora) => new Date(`${fecha}T${(hora||"00:00")}:00-07:00`).getTime();

// ── Confirmación de cita por WhatsApp (una sola función, reutilizada por auto-envío y botón) ──
const TIPO_LEGIBLE_CITA = { primera_vez:"primera vez", seguimiento:"seguimiento" };
const construirMsgConfirmacion = (cita, nombre) => {
  const { fecha } = isoAInputsHmo(cita.inicio);
  const fechaLarga = fecha
    ? new Date(fecha+"T12:00:00").toLocaleDateString("es-MX",{weekday:"long",day:"numeric",month:"long",year:"numeric"})
    : "";
  const hora12h = cita.inicio
    ? new Date(cita.inicio).toLocaleTimeString("es-MX",{timeZone:"America/Hermosillo",hour:"numeric",minute:"2-digit",hour12:true})
    : "";
  const tipoLegible = TIPO_LEGIBLE_CITA[cita.tipo] || "consulta";
  return `Hola ${nombre}, le confirmamos su cita de ${tipoLegible} con el Dr. Gerardo Félix Tapia.\n`
    + `Fecha: ${fechaLarga}\n`
    + `Hora: ${hora12h}\n`
    + `Dirección: Av. Adolfo de la Huerta 200A, 2do piso, Col. Pitic, Hermosillo\n`
    + `Cualquier duda, puede responder por este medio. Quedamos a sus órdenes.`;
};
// Variante para REPROGRAMACIÓN: aclara al paciente que la cita cambió de fecha/hora (no es una cita nueva).
const construirMsgReprogramada = (cita, nombre) => {
  const { fecha } = isoAInputsHmo(cita.inicio);
  const fechaLarga = fecha
    ? new Date(fecha+"T12:00:00").toLocaleDateString("es-MX",{weekday:"long",day:"numeric",month:"long",year:"numeric"})
    : "";
  const hora12h = cita.inicio
    ? new Date(cita.inicio).toLocaleTimeString("es-MX",{timeZone:"America/Hermosillo",hour:"numeric",minute:"2-digit",hour12:true})
    : "";
  const tipoLegible = TIPO_LEGIBLE_CITA[cita.tipo] || "consulta";
  return `Hola ${nombre}, le confirmamos que su cita de ${tipoLegible} con el Dr. Gerardo Félix Tapia ha sido reprogramada.\n`
    + `Nueva fecha: ${fechaLarga}\n`
    + `Nueva hora: ${hora12h}\n`
    + `Dirección: Av. Adolfo de la Huerta 200A, 2do piso, Col. Pitic, Hermosillo\n`
    + `Cualquier duda, puede responder por este medio. Quedamos a sus órdenes.`;
};
// Abre WhatsApp con la confirmación de la cita. Reutiliza enviarWA (formateo 52 + limpieza).
// Devuelve false si no hay teléfono (enviarWA copia el texto al portapapeles).
const enviarConfirmacionCita = (cita, paciente) => {
  const tel = (paciente && paciente.telefono) || "";
  const nombre = (cita && cita.pacienteNombre) || (paciente && paciente.nombre) || "paciente";
  return enviarWA(tel, construirMsgConfirmacion(cita, nombre));
};
// Igual pero con el mensaje de reprogramación (al reagendar).
const enviarReprogramacionCita = (cita, paciente) => {
  const tel = (paciente && paciente.telefono) || "";
  const nombre = (cita && cita.pacienteNombre) || (paciente && paciente.nombre) || "paciente";
  return enviarWA(tel, construirMsgReprogramada(cita, nombre));
};

// FASE B — Migración automática de citas FUTURAS (hoy en adelante) anidadas en p.consultas (esSoloCita)
// al formato v2 en la tabla `citas`. Idempotente. NO borra las viejas (respaldo). NO migra las pasadas.
const migrarCitasFuturas = async (pacientes) => {
  const hoyTs = new Date(hoy()+"T00:00:00").getTime();
  // Cargar citas ya existentes (hoy→futuro) para no duplicar: clave = pacienteId|instante.
  let existentes = [];
  try { existentes = await listarCitas({ desde: hoy()+"T00:00:00" }); }
  catch(e) { console.error("migrarCitasFuturas: no se pudieron leer citas existentes:", e); }
  const claves = new Set(existentes.map(c =>
    `${c.pacienteId||c.pacienteNombre}|${new Date(c.inicio).getTime()}`));

  let migradas = 0, fallidas = 0;
  const pacSet = new Set();
  for (const p of (pacientes||[])) {
    const futuras = (p.consultas||[]).filter(c =>
      c.esSoloCita && parseFechaClinica(c.proxCita||c.fecha) >= hoyTs);
    for (const c of futuras) {
      const fecha = toISODate(c.proxCita||c.fecha) || (c.proxCita||c.fecha);
      const hora  = c.proxHora || c.hora || "09:00";
      const key = `${p.id||p.nombre}|${_instanteHermosillo(fecha,hora)}`;
      if (claves.has(key)) continue; // ya migrada → idempotente
      const glp = (p.ci && p.ci.glp1) || "";
      const dm = glp.match(/([\d.]+\s*mg)/i);
      const datos = {
        pacienteId: p.id || null,
        pacienteNombre: p.nombre || "",
        tipo: c.tipoCita === "primera" ? "primera_vez" : "seguimiento",
        medicamento: glp ? abrevMed(glp) : null,
        dosis: dm ? dm[1].replace(/\s+/g,"") : null,
        fecha, hora,
      };
      try {
        const res = await agendarCitaV2(datos, crearCita); // crea evento en calendario dedicado + inserta en tabla
        if (res.ok) { migradas++; pacSet.add(p.id||p.nombre); claves.add(key); }
        else fallidas++;
      } catch(e) { console.error("migrarCitasFuturas: fallo en una cita:", e); fallidas++; }
    }
  }
  return { migradas, pacientes: pacSet.size, fallidas };
};

