const AutocompleteCIE10 = ({value, onChange}) => {
  const [busq, setBusq] = useState(value || "");
  const [mostrar, setMostrar] = useState(false);
  const ref = useRef(null);

  useEffect(()=>{ setBusq(value||""); },[value]);

  useEffect(()=>{
    const fuera = (e) => { if (ref.current && !ref.current.contains(e.target)) setMostrar(false); };
    document.addEventListener("mousedown", fuera);
    document.addEventListener("touchstart", fuera);
    return ()=>{
      document.removeEventListener("mousedown", fuera);
      document.removeEventListener("touchstart", fuera);
    };
  },[]);

  const filtrados = busq.trim().length >= 2
    ? CIE10.filter(c=>{
        const q = busq.toLowerCase();
        return c.c.toLowerCase().includes(q) || c.d.toLowerCase().includes(q);
      }).slice(0,8)
    : [];

  const seleccionar = (c) => {
    const txt = c.c + " - " + c.d;
    setBusq(txt);
    onChange(txt);
    setMostrar(false);
  };

  return (
    <div style={{position:"relative"}} ref={ref}>
      <label style={{fontSize:11,fontWeight:600,color:C.suave,display:"block",marginBottom:4}}>
        Diagnóstico principal (CIE-10)
      </label>
      <input type="text" value={busq}
        onChange={e=>{setBusq(e.target.value); onChange(e.target.value); setMostrar(true);}}
        onFocus={()=>setMostrar(true)}
        placeholder="Empieza a escribir... ej. obesidad, diabetes, hipotiroidismo"
        style={{width:"100%",padding:"9px 12px",borderRadius:8,
          border:"1.5px solid "+C.grisMedio,fontSize:14,boxSizing:"border-box"}}/>
      {mostrar && filtrados.length>0 && (
        <div style={{position:"absolute",top:"100%",left:0,right:0,zIndex:100,
          background:"white",border:"1px solid "+C.grisMedio,borderRadius:8,
          marginTop:2,maxHeight:280,overflow:"auto",
          boxShadow:"0 4px 12px rgba(0,0,0,0.1)"}}>
          {filtrados.map((c,i)=>(
            <div key={i} onClick={()=>seleccionar(c)}
              style={{padding:"8px 12px",cursor:"pointer",fontSize:12,
                borderBottom:i<filtrados.length-1?"1px solid "+C.gris:"none"}}
              onMouseEnter={e=>e.currentTarget.style.background=C.azulPale}
              onMouseLeave={e=>e.currentTarget.style.background="white"}>
              <span style={{fontWeight:800,color:C.azul,marginRight:8}}>{c.c}</span>
              <span style={{color:C.texto}}>{c.d}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

