// Elimina acentos y reemplaza espacios/caracteres especiales con guión bajo
const sanitizeFilename = (str) =>
  (str||"").normalize("NFD").replace(/[̀-ͯ]/g,"")
    .replace(/[^a-zA-Z0-9\-]/g,"_").replace(/_+/g,"_").replace(/^_|_$/g,"");

// ── Núcleo de generación de PDF ───────────────────────────────
// Si el contenido tiene elementos .pdf-page → cada uno se captura como UNA página carta (816×1056px @96dpi).
// Si no, y singlePage=true → toda la captura a 1 página carta. Si no, paginado mm clásico.
const LETTER_PX = [816, 1056];
const construirPDF = async (contentRef, {singlePage=false}={}) => {
  const [{default: jsPDF}, {default: html2canvas}] = await Promise.all([
    import("jspdf"), import("html2canvas")
  ]);
  const root = contentRef.current;
  const render = (el) => html2canvas(el, { scale: 2, useCORS: true, backgroundColor: "#ffffff", logging: false });
  const pageEls = root.querySelectorAll(".pdf-page");

  // Documento compuesto por páginas fijas → 1 .pdf-page = 1 hoja carta
  if (pageEls.length > 0) {
    const pdf = new jsPDF({orientation: "portrait", unit: "px", format: LETTER_PX});
    for (let i = 0; i < pageEls.length; i++) {
      const canvas = await render(pageEls[i]);
      if (i > 0) pdf.addPage(LETTER_PX, "portrait");
      let w = 816, h = 816 * (canvas.height / canvas.width);
      if (h > 1056) { h = 1056; w = 1056 * (canvas.width / canvas.height); } // contenido más alto → ajustar para caber
      pdf.addImage(canvas.toDataURL("image/png", 0.95), "PNG", (816 - w) / 2, 0, w, h);
    }
    return pdf;
  }

  const canvas = await render(root);
  const imgData = canvas.toDataURL("image/png", 0.95);
  if (singlePage) {
    const pdf = new jsPDF({orientation: "portrait", unit: "px", format: LETTER_PX});
    pdf.addImage(imgData, "PNG", 0, 0, 816, 1056);
    return pdf;
  }
  const pdf = new jsPDF({orientation: "portrait", unit: "mm", format: "letter"});
  const margin = 10;
  const pdfW = pdf.internal.pageSize.getWidth() - margin * 2;
  const pdfH = pdf.internal.pageSize.getHeight() - margin * 2;
  const imgH = pdfW * (canvas.height / canvas.width);
  if (imgH <= pdfH) {
    pdf.addImage(imgData, "PNG", margin, margin, pdfW, imgH);
  } else {
    let y = 0;
    while (y < imgH - 0.5) { if (y > 0) pdf.addPage(); pdf.addImage(imgData, "PNG", margin, margin - y, pdfW, imgH); y += pdfH; }
  }
  return pdf;
};

// ── PDF helper: genera un blob PDF desde un ref renderizado (para compartir en móvil) ──
// Usa el núcleo construirPDF: detecta .pdf-page (multi-página fija) o singlePage (1 hoja).
const generarPDFBlob = async (contentRef, filename, {singlePage=false}={}) => {
  try {
    const pdf = await construirPDF(contentRef, {singlePage});
    const blob = new Blob([pdf.output("arraybuffer")], { type: "application/pdf" });
    const file = new File([blob], filename || "documento.pdf", { type: "application/pdf" });
    const url = URL.createObjectURL(file); // UNA sola Object URL, derivada del MISMO file que se comparte
    return { blob, url, file };
  } catch(e) { console.error("PDF blob error:", e); return null; }
};

// Comparte/abre un PDF YA preparado. iOS-safe: Web Share API si se puede, si no abre el blob en pestaña vía <a>.
// Nunca usa window.open() en setTimeout (bloqueado por iOS Safari).
const compartirOAbrirPDF = async ({file, url, filename}) => {
  // Móvil: Web Share SOLO con el archivo (sin text — adjuntar archivo + texto duplica el PDF en WhatsApp/macOS).
  if (file && navigator.canShare && navigator.canShare({ files: [file] })) {
    try { await navigator.share({ files: [file], title: filename || "Documento" }); }
    catch(e) { /* usuario canceló → no hacer nada más */ }
    return; // crítico: no caer al fallback de escritorio
  }
  // Escritorio / sin Web Share de archivos: abrir el PDF en pestaña nueva UNA sola vez.
  // Usar la url que ya viene de generarPDFBlob (derivada del file) — NO crear una segunda Object URL.
  const blobURL = url;
  if (!blobURL) return;
  window.open(blobURL, "_blank");
  setTimeout(() => { try { URL.revokeObjectURL(blobURL); } catch(e) {} }, 300000);
};

// ── Print Modal ───────────────────────────────────────────────
// onWAConPDF(ref, titulo, done) — descarga PDF + abre WhatsApp Desktop
const PrintModal = ({titulo, children, onClose, onWA, onWAConPDF, extraHeader, pdfFilename}) => {
  const ref = useRef();
  const isGenerating = useRef(false);

  const print = () => {
    try {
      const iframe = document.createElement("iframe");
      iframe.style.cssText = "position:fixed;right:-9999px;bottom:-9999px;width:8.5in;height:11in;border:0";
      document.body.appendChild(iframe);
      const css = "*{margin:0;padding:0;box-sizing:border-box;-webkit-print-color-adjust:exact!important}body{font-family:Arial,sans-serif;padding:8mm;color:#1A2332;background:white}img{max-width:100%}@page{margin:8mm;size:letter}";
      const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${titulo||"Reporte"}</title><style>${css}</style></head><body>${ref.current.innerHTML}</body></html>`;
      const doc = iframe.contentWindow.document;
      doc.open(); doc.write(html); doc.close();
      setTimeout(()=>{ try{ iframe.contentWindow.focus(); iframe.contentWindow.print(); setTimeout(()=>{ try{document.body.removeChild(iframe);}catch(e){} },5000); }catch(e){ alert("No se pudo imprimir"); try{document.body.removeChild(iframe);}catch(e){} } },500);
    } catch(e) { alert("Error: "+e.message); }
  };

  const handleCompartirPDF = async () => {
    if (isGenerating.current) return;
    isGenerating.current = true;
    try {
      const fname = pdfFilename || (sanitizeFilename(titulo||"Documento") + ".pdf");
      // singlePage:false → construirPDF usa los .pdf-page si existen (receta/progreso) o pagina por contenido (HC/nota/labs)
      const pdf = await generarPDFBlob(ref, fname, { singlePage: false });
      if (pdf) await compartirOAbrirPDF({ file: pdf.file, url: pdf.url, filename: fname });
    } finally { isGenerating.current = false; }
  };

  const handleWA = () => {
    if (onWAConPDF) {
      if (isGenerating.current) return;
      isGenerating.current = true;
      onWAConPDF(ref, titulo, () => { isGenerating.current = false; });
    } else {
      onWA?.();
    }
  };

  return (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.6)",zIndex:3000,
      display:"flex",alignItems:"flex-start",justifyContent:"center",padding:20,overflow:"auto"}}>
      <div style={{background:"white",borderRadius:16,width:"100%",maxWidth:730,
        maxHeight:"92vh",overflow:"hidden",display:"flex",flexDirection:"column"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",
          padding:"12px 20px",background:C.azul}}>
          <span style={{fontWeight:800,color:"white",fontSize:13}}>{titulo}</span>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            {extraHeader}
            {(onWA || onWAConPDF) && (
              <button onClick={handleWA} style={{padding:"7px 16px",borderRadius:8,border:"none",
                background:"#25D366",color:"white",cursor:"pointer",fontWeight:700,fontSize:12}}>
                📱 WhatsApp
              </button>
            )}
            <button onClick={handleCompartirPDF} style={{padding:"7px 16px",borderRadius:8,border:"none",
              background:C.morado,color:"white",cursor:"pointer",fontWeight:700,fontSize:12}}>
              📤 Compartir PDF
            </button>
            <button onClick={print} style={{padding:"7px 16px",borderRadius:8,border:"none",
              background:"white",color:C.azul,cursor:"pointer",fontWeight:700,fontSize:12}}>
              🖨️ Imprimir
            </button>
            <button onClick={onClose} style={{background:"rgba(255,255,255,.2)",border:"none",
              fontSize:20,cursor:"pointer",color:"white",borderRadius:6,padding:"2px 8px"}}>×</button>
          </div>
        </div>
        <div style={{overflow:"auto",flex:1,padding:20}}>
          <div ref={ref} style={{background:"white",padding:"16px 24px 24px",maxWidth:660,
            margin:"0 auto",border:"1px solid "+C.grisMedio,borderRadius:8}}>
            {children}
          </div>
        </div>
      </div>
    </div>
  );
};

